// pages/UserProfile.tsx
import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { apiService } from '../services/api';

const UserProfile: React.FC = () => {
  const { user, updateUser } = useAuth();
  const [minioInfo, setMinioInfo] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [userFiles, setUserFiles] = useState<any[]>([]);

  useEffect(() => {
    const loadUserData = async () => {
      if (user) {
        try {
          const [info, files] = await Promise.all([
            apiService.getUserMinioInfo(),
            apiService.getUserFiles()
          ]);
          setMinioInfo(info);
          setUserFiles(files);
        } catch (error) {
          console.error('Error loading user data:', error);
        } finally {
          setLoading(false);
        }
      }
    };

    loadUserData();
  }, [user]);

  if (!user) {
    return <div>Please login to view your profile</div>;
  }

  if (loading) {
    return <div>Loading profile...</div>;
  }

  return (
    <div className="user-profile">
      <div className="profile-header">
        <h1>👤 Use Profile</h1>
        <div className="user-badge">
          {user.is_admin ? '👑 Admin' : '👤 User'}
        </div>
      </div>

      <div className="profile-grid">
        <div className="profile-card">
          <h2>Account Information</h2>
          <div className="info-item">
            <label>Username:</label>
            <span>{user.username}</span>
          </div>
          {user.email && (
            <div className="info-item">
              <label>Email:</label>
              <span>{user.email}</span>
            </div>
          )}
          {user.created_at && (
            <div className="info-item">
              <label>Member Since:</label>
              <span>{new Date(user.created_at).toLocaleDateString()}</span>
            </div>
          )}
          <div className="info-item">
            <label>Status:</label>
            <span className="status-active">Active</span>
          </div>
        </div>


      </div>

      <div className="user-files">
        <h2>Your Files ({userFiles.length})</h2>
        {userFiles.length > 0 ? (
          <div className="files-list">
            {userFiles.map((file, index) => (
              <div key={index} className="file-item">
                <div className="file-icon">📄</div>
                <div className="file-details">
                  <div className="file-name">{file.name || file.object_name}</div>
                  <div className="file-meta">
                    <span>Size: {(file.size / 1024).toFixed(2)} KB</span>
                    {file.last_modified && (
                      <span>Modified: {new Date(file.last_modified).toLocaleDateString()}</span>
                    )}
                  </div>
                </div>
                <a href={file.url} target="_blank" rel="noopener noreferrer" className="file-link">
                  Open
                </a>
              </div>
            ))}
          </div>
        ) : (
          <p className="no-files">No files uploaded yet.</p>
        )}
      </div>
    </div>
  );
};

export default UserProfile;
